#!/usr/bin/env python3
"""Build the offline example board from reviewed job-snapshot.csv. No network, dependencies or auto-verification."""
import csv, datetime as dt, html, os
from collections import Counter
from pathlib import Path
from urllib.parse import urlsplit

HOME=Path(__file__).resolve().parent
GROUPS=[('Remote from Ontario','01','Fully remote from Ontario','These postings explicitly include Canada or Ontario. Individual residency, language and hours requirements still apply.'),('Toronto','02','Toronto office roles','Hybrid, on-site, occasional visits or conflicting work policies. These are Toronto matches, not no-office remote matches.'),('Global — confirm Ontario','03','Global remote · confirm Ontario','The employer says global remote, but Canadian employment arrangements are not explicit. Not counted among Ontario-eligible matches.')]
TRACKS=['ServiceNow','Salesforce','Other']
ESC=lambda v: html.escape(str(v), quote=True)
def url(u):
    assert urlsplit(u).scheme in ('http','https') and urlsplit(u).netloc, 'not an absolute posting URL'
    return ESC(u)
def date(s):return dt.date.fromisoformat(s)
def pretty(d):return f'{d:%b} {d.day}, {d.year}'
def link(u,text,cls=''):return f'<a class="{cls}" href="{url(u)}" target="_blank" rel="noopener noreferrer">{ESC(text)} <span aria-hidden="true">↗</span></a>'
def cell(label,v):return f'<div><dt>{label}</dt><dd>{ESC(v)}</dd></div>'
def card(j,asof):
    tr=j['category']; gid=j['geo_bucket']; posted=date(j['posted_on']) if j['posted_on'] else None
    age=(asof-posted).days if posted else None
    fresh='recent' if age is not None and 0<=age<=30 else ('older' if age is not None else 'undated')
    date_label=('Posted '+pretty(posted) if posted else 'Posted date unverified')
    if fresh=='older': date_label+=' · older listing'
    agency=j['hiring_channel']=='Recruiter / agency'; org=j['publisher'] if j['employer_or_client']=='Undisclosed client' else j['employer_or_client']
    by='Recruiter · client undisclosed' if j['employer_or_client']=='Undisclosed client' else ('Via '+j['publisher'] if agency or j['employer_or_client']!=j['publisher'] else 'Direct employer')
    if j['publisher']=='EQ Bank':by='Direct employer'
    if j['publisher']=='Hydro One TalentNet':by='Employer contractor portal'
    cls=tr.lower(); clos='';
    if j['closes_on']:clos='<span class="due">Closes '+ESC(pretty(date(j['closes_on'])))+'</span>'
    details=cell('Work location',j['geo_evidence'])+cell('Status at check',j['open_evidence'])+cell('Date source',j['date_evidence'])
    if j['valid_through']:details+=cell('Structured expiry (not a deadline)',j['valid_through'])
    extra='';ap=j['apply_entry_url'];cor=j['corroborating_url']
    if ap and ap!=j['posting_url'] and j['access_level']=='Form reached':extra+=link(ap,'Application form','secondlink')
    if cor and cor!=j['posting_url']:extra+=link(cor,'Issuer list / API','secondlink')
    details+=cell('Posting ID',j['posting_id']);attrs=' '.join(f'data-{k}="{ESC(v)}"' for k,v in [('track',tr),('geo',gid),('date',fresh),('channel','agency' if agency else 'direct')])
    return f'''<article class="role {cls}" {attrs}><div class="flagrow"><span class="pill {cls}">{ESC(tr if tr!='Other' else 'Other · adjacent')}</span><span class="status">{ESC(j['access_level'])}</span></div>
<h3>{link(j['posting_url'],j['title'],'titlelink')}</h3><p class="org">{ESC(org)}</p><p class="by">{ESC(by)}</p>
<dl class="facts">{cell('Where',j['location_summary'])}{cell('Pay',j['pay_as_listed'])}{cell('Terms',j['employment'])}</dl>
<p class="duties">{ESC(j['developer_evidence'])}</p><p class="note">{ESC(j['candidate_note'])}</p>
<div class="when"><span>{ESC(date_label)}</span>{clos}</div><div class="actions">{link(j['posting_url'],'View posting','cta')}</div>
<details><summary>Evidence &amp; access</summary><dl class="evidence">{details}</dl>{extra}</details></article>'''

def main():
    with (HOME/'job-snapshot.csv').open(encoding='utf-8',newline='') as f:jobs=list(csv.DictReader(f))
    if not jobs:raise ValueError('empty snapshot')
    if len(set((j['publisher'],j['posting_id']) for j in jobs))!=len(jobs):raise ValueError('duplicate publication ID within issuer')
    if len(set(j['checked_local_date'] for j in jobs))!=1:raise ValueError('This is a single-batch snapshot renderer; do not label mixed verification dates as one check.')
    asof=date(jobs[0]['checked_local_date']); counts=Counter(j['geo_bucket'] for j in jobs)
    if any(j['category'] not in TRACKS or j['geo_bucket'] not in [g[0] for g in GROUPS] for j in jobs):raise ValueError('unmapped track or work bucket')
    local=[j for j in jobs if j['geo_bucket']!=GROUPS[2][0]]; platform=sum(j['category']!='Other' for j in local); other=len(local)-platform
    sections=''
    for group,num,header,sub in GROUPS:
        picks=[j for j in jobs if j['geo_bucket']==group]
        if not picks:continue
        body=''.join(card(j,asof) for j in picks)
        sections+=f'<section class="block"><div class="blockhead"><span class="num">{num}</span><div><h2>{ESC(header)} <span class="gcount">{len(picks)}</span></h2><p>{ESC(sub)}</p></div></div><div class="grid">{body}</div></section>'
    opt=lambda v: f'<option value="{ESC(v)}">{ESC(v)}</option>'
    doc=TOP.replace('%%ASOF%%',pretty(asof)).replace('%%PLATFORM%%',str(platform)).replace('%%OTHER%%',str(other)).replace('%%CONFIRM%%',str(counts[GROUPS[2][0]])).replace('%%TRACKS%%',''.join(map(opt,TRACKS))).replace('%%GEO%%',''.join(opt(g[0]) for g in GROUPS)).replace('%%N%%',str(len(jobs)))+sections+END
    target=HOME/'board.html';tmp=target.with_suffix('.html.tmp');tmp.write_text(doc,encoding='utf-8');os.replace(tmp,target);print(f'Wrote {target.name}: {len(jobs)} listings; {platform} in-scope platform roles, {other} in-scope adjacent, {counts[GROUPS[2][0]]} country check.')

TOP='''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Platform openings • Toronto &amp; remote</title><style>
:root{--paper:#f7f7f2;--ink:#162b2a;--soft:#465a56;--line:#c7d1c9;--green:#135c50;--yellow:#e2ab47;--orange:#9b462c;--blue:#275c85}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}a{color:var(--green);text-underline-offset:.16em}a:focus-visible,summary:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #d18222;outline-offset:3px}main,.wrap{max-width:1170px;margin:auto;padding:0 clamp(1rem,4vw,3.2rem)}header{background:#12382f;color:#f9f8ed;border-top:7px solid var(--yellow);padding:2.1rem 0 1.9rem}.mastline{display:flex;justify-content:space-between;gap:.5rem;flex-wrap:wrap;font:700 .76rem/1.6 ui-monospace,monospace;letter-spacing:.11em;text-transform:uppercase;color:#d5e6db}.mastline span:first-child{color:#f4cd85}h1,h2,h3{margin:0;text-wrap:balance}h1{font:normal clamp(2.6rem,5.6vw,4.6rem)/1.05 Georgia,serif;letter-spacing:-.035em;margin:1.05rem 0 .6rem}header p{color:#dfebe2;max-width:72ch;margin:0}.stats{display:flex;flex-wrap:wrap;gap:.65rem 1.55rem;border-top:1px solid #507469;margin-top:1.4rem;padding-top:1rem}.stats span{font-size:.89rem;color:#e7eee7}.stats b{font:600 1.2rem/1.3 ui-monospace,monospace;color:white}.control{border-bottom:1px solid var(--line);padding:1.25rem 0 .7rem}.filters{display:flex;align-items:flex-end;flex-wrap:wrap;gap:.65rem}.filters label{display:block;color:var(--soft);font-size:.76rem;font-weight:700}.filters input,.filters select,.filters button{display:block;background:white;border:1px solid #9ead9f;border-radius:5px;color:var(--ink);font:400 .92rem/1.2 system-ui;padding:.45rem .55rem;min-height:2.4rem;margin-top:3px}.filters input{max-width:100%;width:15em}.filters button{cursor:pointer;font-weight:600;background:transparent}#tally{font:.8rem/1.5 ui-monospace,monospace;color:var(--soft);margin:.65rem 0 0}.block{margin:2rem 0 3rem}.blockhead{display:flex;gap:1rem;align-items:flex-start;margin-bottom:1rem}.num{font:600 .8rem/1.1 ui-monospace,monospace;padding:.55rem;border:1px solid var(--line);border-radius:50%;color:var(--green)}h2{font:500 clamp(1.65rem,4vw,2.35rem)/1.12 Georgia,serif;letter-spacing:-.025em}.blockhead p{line-height:1.4;color:var(--soft);font-size:.93rem;margin:.35rem 0 0}.gcount{font:600 .8rem/1 ui-monospace,monospace;vertical-align:middle;color:var(--soft)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.role{border:1px solid var(--line);border-radius:8px;background:#fffffb;padding:1.15rem 1.25rem;display:flex;flex-direction:column;min-width:0}.flagrow,.when{display:flex;justify-content:space-between;gap:.4rem;align-items:center;flex-wrap:wrap}.pill{display:inline-block;border-radius:4px;padding:.18rem .5rem;font-size:.73rem;font-weight:750;letter-spacing:.025em}.pill.servicenow{background:#d7eee0;color:#124836}.pill.salesforce{background:#daebf7;color:#224e6c}.pill.other{background:#e9e3f0;color:#523a68}.status,.by,.when,.evidence dt,.facts dt{font-size:.78rem;color:var(--soft)}.status{font-family:ui-monospace,monospace;font-size:.72rem}h3{font-size:1.35rem;line-height:1.22;letter-spacing:-.02em;margin:.8rem 0 .22rem}.titlelink{color:var(--ink);text-decoration:none}.titlelink:hover{text-decoration:underline}.titlelink span{font-size:.72em;color:var(--green)}.org{font-weight:680;margin:0}.by{margin:0 0 .7rem}.facts{border-block:1px solid #dce2dd;padding:.45rem 0;margin:.1rem 0 .6rem}.facts div{display:grid;grid-template-columns:3em 1fr;gap:.4rem;margin:.12rem 0}.facts dd{font-size:.88rem}.facts dd,.evidence dd{margin:0}.duties{margin:.1rem 0 .2rem;font-size:.94rem}.note{color:var(--soft);margin:.1rem 0 .8rem;font-size:.87rem}.when{margin-top:auto;padding-top:.2rem}.due{color:var(--orange);font-weight:700}.actions{margin:.75rem 0}.cta{font-size:.85rem;font-weight:700;background:var(--green);color:white;border-radius:4px;display:inline-block;padding:.43rem .7rem;text-decoration:none}.cta:hover{background:#0b4439}.secondlink{font-size:.85rem;margin-right:1em}.role details{border-top:1px solid #dee4de;padding-top:.5rem}.role summary{cursor:pointer;color:var(--green);font-weight:630;font-size:.85rem}.evidence{font-size:.86rem;margin:.4rem 0}.evidence div{margin:.35rem 0}.evidence dt{font-weight:700}.evidence dd{overflow-wrap:anywhere}.foot{color:var(--soft);font-size:.88rem;border-block-start:1px solid var(--line);padding:1.2rem 0 2rem}.none{border:1px dashed var(--line);padding:1rem}.js-only{display:none}.js .js-only{display:block}[hidden]{display:none!important}@media(max-width:690px){.grid{grid-template-columns:1fr}.blockhead{gap:.65rem}.filters input{width:13rem}.role{padding:1rem}.num{display:none}}@media print{body{background:white;font-size:10pt}.control,.actions,.role details,footer .tip{display:none}.role{break-inside:avoid;padding:.65rem}.grid{grid-template-columns:1fr 1fr}.block{margin:1rem 0}header{background:white;color:var(--ink);padding:.6rem 0;border-color:var(--green)}header p,.stats b,.stats span,.mastline,.mastline span:first-child{color:var(--ink)}h1{font-size:26pt}}
</style></head><body><header><div class="wrap"><div class="mastline"><span>Toronto / Ontario · job research</span><span>Checked %%ASOF%% · Toronto time</span></div><h1>Platform openings</h1><p>ServiceNow and Salesforce development, plus adjacent integration and data roles. Each card links to the issuing employer or recruiter and shows what was actually checked.</p><div class="stats"><span><b>%%PLATFORM%%</b> platform matches</span><span><b>%%OTHER%%</b> adjacent matches</span><span><b>%%CONFIRM%%</b> global lead to confirm</span></div></div></header><main><div class="control js-only"><div class="filters"><label>Track<select id="track"><option value="">All tracks</option>%%TRACKS%%</select></label><label>Location<select id="geo"><option value="">All arrangements</option>%%GEO%%</select></label><label>Issuer date<select id="date"><option value="">Any posting date</option><option value="recent">Last 30 days at check</option><option value="older">Older, still listed</option><option value="undated">Not verified</option></select></label><label>Channel<select id="channel"><option value="">All channels</option><option value="direct">Direct / employer portal</option><option value="agency">Recruiter / agency</option></select></label><label>Search<input type="search" id="find" placeholder="Employer, skill or title"></label><button type="button" id="clear">Reset</button></div><p id="tally" role="status" aria-live="polite">Showing %%N%% of %%N%% listings</p></div><p class="none" id="none" hidden>No roles match these filters. Try another track or clear the search.</p>'''
END='''</main><footer class="wrap"><div class="foot"><b>How to read the evidence:</b> “Form reached” means a role-specific application form opened, not that anyone applied. “Apply shown” means a role-specific control or link was visible. “Gated route” stops at a login or consent step. “Listed” means the issuer listed the role, not that the form was tested. This is a dated research snapshot, not a live feed. Recheck the role before applying. <span class="tip">For sources, operating instructions and reuse conditions, see AGENT-RUNBOOK.md in the kit.</span></div></footer><script>
(()=>{document.documentElement.classList.add('js');const cards=[...document.querySelectorAll('article.role')],filters=['track','geo','date','channel'].map(i=>document.getElementById(i)),f=document.getElementById('find');function applyFilters(){const q=f.value.toLowerCase().trim(),words=q?q.split(/\\s+/):[];let n=0;for(const c of cards){const match=filters.every(s=>!s.value||c.dataset[s.id]===s.value)&&words.every(w=>c.textContent.toLowerCase().includes(w));c.hidden=!match;if(match)n++;}for(const s of document.querySelectorAll('section.block')){const x=s.querySelectorAll('article:not([hidden])').length;s.hidden=x===0;s.querySelector('.gcount').textContent=x;}document.getElementById('tally').textContent='Showing '+n+' of '+cards.length+' listings';document.getElementById('none').hidden=!!n;}filters.forEach(s=>s.addEventListener('change',applyFilters));f.addEventListener('input',applyFilters);document.getElementById('clear').addEventListener('click',()=>{filters.forEach(s=>s.value='');f.value='';applyFilters()});applyFilters()})();</script></body></html>'''
if __name__=='__main__':main()
